// List of all district names
const districtNames = Object.keys(villagesByDistrict);

// Flat list of every village, each tagged with its district
const allVillages = districtNames.flatMap((district) =>
    villagesByDistrict[district].map((name) => ({ district, name }))
);

if (typeof module !== "undefined" && module.exports) {
    module.exports = { villagesByDistrict, districtNames, allVillages };
}

if (typeof globalThis !== "undefined") {
    globalThis.villagesByDistrict = villagesByDistrict;
    globalThis.districtNames = districtNames;
    globalThis.allVillages = allVillages;
}